const lead = JSON.parse(JSON.stringify($json));
const finalStatus = lead.qualification?.final_status ?? null;
const processingStatus = lead.processing?.status ?? null;
const nextAction = lead.crm?.next_action ?? null;
const assignedRepId = lead.routing?.assigned_sales_rep_id ?? null;
let required = false;
let reason = 'followup_not_required';
if (finalStatus === 'qualified' && processingStatus === 'processing' && nextAction === 'sales_follow_up' && assignedRepId !== null) {
  required = true;
  reason = 'qualified_followup';
} else if (finalStatus === 'nurture' && processingStatus === 'processing' && nextAction === 'start_nurture_sequence') {
  required = true;
  reason = 'nurture_followup';
} else if (finalStatus === 'vip' || nextAction === 'await_manager_approval') {
  reason = 'vip_waiting_approval';
} else if (nextAction === 'manual_sales_assignment') {
  reason = 'manual_sales_assignment';
} else if (finalStatus === 'manual_review' || processingStatus === 'manual_review') {
  reason = 'manual_review';
} else if (finalStatus === 'unqualified' || lead.crm?.stage === 'closed') {
  reason = 'unqualified_or_closed';
} else if (processingStatus === 'completed') {
  reason = 'completed';
}
lead.wf05_handoff = { required, reason };
return [{ json: lead }];

const lead = JSON.parse(JSON.stringify($json));
delete lead.wf05_handoff;
return [{ json: lead }];
